input.command:
$candidates = @(
  "C:\Program Files\Git\cmd\git.exe",
  "C:\Program Files\Git\bin\git.exe",
  "C:\Program Files (x86)\Git\cmd\git.exe",
  "$env:LOCALAPPDATA\Programs\Git\cmd\git.exe",
  "C:\Program Files\GitHub CLI\gh.exe",
  "$env:LOCALAPPDATA\Programs\GitHub CLI\gh.exe",
  "$env:ProgramFiles\GitHub CLI\gh.exe"
);
foreach ($p in $candidates) { if (Test-Path $p) { "FOUND: $p" } };
Write-Host "--- where.exe ---";
where.exe git 2>&1;
where.exe gh 2>&1;
Write-Host "--- PATH snippet ---";
$env:PATH -split ';' | Where-Object { $_ -match 'Git|gh|github' };
Write-Host "--- .git exists? ---";
Test-Path "C:\Users\Administrator\Desktop\docuverse-kanzheli-main\.git";
Get-ChildItem "C:\Users\Administrator\Desktop\docuverse-kanzheli-main" -Force | Select-Object Name, Mode | Format-Table -AutoSize;
Write-Host "--- search Program Files ---";
Get-ChildItem "C:\Program Files" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'Git|GitHub' } | Select-Object FullName;
Get-ChildItem "$env:LOCALAPPDATA\Programs" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'Git|GitHub' } | Select-Object FullName;
Write-Host "--- winget ---";
winget list --name Git 2>&1 | Select-Object -First 20;
winget list --name "GitHub CLI" 2>&1 | Select-Object -First 10;

Get-ChildItem "C:\Users\Administrator\Desktop\docuverse-kanzheli-main" -Force | ForEach-Object { $_.Name };
Write-Host "---";
Get-Command scoop, choco, winget, npm, node, curl, Invoke-WebRequest -ErrorAction SilentlyContinue | Format-Table Name, Source -AutoSize;
Write-Host "--- AppX winget ---";
Get-AppxPackage -Name "*DesktopAppInstaller*" -ErrorAction SilentlyContinue | Select-Object Name, Version, InstallLocation;
Write-Host "--- search common bins ---";
@(
  "C:\Program Files\nodejs\node.exe",
  "$env:APPDATA\npm\gh.cmd",
  "C:\Windows\System32\curl.exe",
  "$env:USERPROFILE\scoop\shims\git.exe",
  "$env:USERPROFILE\scoop\shims\gh.exe"
) | ForEach-Object { if (Test-Path $_) { "FOUND $_" } else { "MISS $_" } }

Write-Host "Desktop folders:"; Get-ChildItem "C:\Users\Administrator\Desktop" -Directory | ForEach-Object { $_.Name };
Write-Host "--- winget source ---";
& "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe" --version 2>&1;
Write-Host "--- try install git ---";
& "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe" install --id Git.Git -e --accept-source-agreements --accept-package-agreements --disable-interactivity 2>&1;

Write-Host "Desktop folders:"; Get-ChildItem "C:\Users\Administrator\Desktop" -Directory | ForEach-Object { $_.Name };
Write-Host "--- winget source ---";
& "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe" --version 2>&1;
Write-Host "--- try install git ---";
& "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe" install --id Git.Git -e --accept-source-agreements --accept-package-agreements --disable-interactivity 2>&1;
